svg.metadata:
@prefix : <#> .
@prefix bgf: <https://bg-rdf.org/ontologies/bondgraph-framework#> .
@prefix cdt: <https://w3id.org/cdt/> .
@prefix celldl: <http://celldl.org/ontologies/celldl#> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .

<> a celldl:Document, bgf:BondgraphModel ;
  dcterms:created "2026-10-27T00:33:28.827Z" ;
  dcterms:modified "2026-10-27T00:33:31.056Z" ;
  owl:versionInfo "1.0" ;
  bgf:hasSignalBlock :ID-00000001, :ID-00000002, :ID-00000003, :ID-00000004 ;
  bgf:hasSignalBond :ID-00000005, :ID-00000006, :ID-00000007 ;
  <https://physiomelinks.github.io/ns/celldl#unitSystem> <https://physiomelinks.github.io/ns/celldl#Cellular> .

:ID-00000001 a celldl:Component, bgf:SignalOutputPort ;
  bgf:hasSymbol "f_ab" ;
  bgf:portType "baroreceptor_firing_rate_port" .

:ID-00000002 a celldl:Component, bgf:SigmoidMap ;
  bgf:hasSymbol "f_sig" ;
  bgf:parameterValue [
    bgf:hasSymbol "f_ab_min" ;
    bgf:hasValue "2.52 s-1"^^cdt:ucum ;
    bgf:varName "y_min"
  ], [
    bgf:hasSymbol "f_ab_max" ;
    bgf:hasValue "47.78 s-1"^^cdt:ucum ;
    bgf:varName "y_max"
  ], [
    bgf:hasSymbol "P_nom" ;
    bgf:hasValue "12 kPa"^^cdt:ucum ;
    bgf:varName "u_nom"
  ], [
    bgf:hasSymbol "k_ab" ;
    bgf:hasValue "1.6 kPa"^^cdt:ucum ;
    bgf:varName "k"
  ] .

:ID-00000003 a celldl:Component, bgf:FirstOrderLag ;
  bgf:hasSymbol "P_baro" ;
  bgf:hasValue "12 kPa"^^cdt:ucum ;
  bgf:parameterValue [
    bgf:hasSymbol "tau_pb" ;
    bgf:hasValue "2.076 s"^^cdt:ucum ;
    bgf:varName "tau"
  ] .

:ID-00000004 a celldl:Component, bgf:SignalInputPort ;
  bgf:hasSymbol "P_sys" ;
  bgf:hasValue "13 kPa"^^cdt:ucum ;
  bgf:portType "arterial_pressure_port" .

:ID-00000005 a celldl:Connection, bgf:SignalBond ;
  celldl:hasSource :ID-00000004 ;
  celldl:hasTarget :ID-00000003 ;
  bgf:hasSource :ID-00000004 ;
  bgf:hasTarget :ID-00000003 .

:ID-00000006 a celldl:Connection, bgf:SignalBond ;
  celldl:hasSource :ID-00000003 ;
  celldl:hasTarget :ID-00000002 ;
  bgf:hasSource :ID-00000003 ;
  bgf:hasTarget :ID-00000002 .

:ID-00000007 a celldl:Connection, bgf:SignalBond ;
  celldl:hasSource :ID-00000002 ;
  celldl:hasTarget :ID-00000001 ;
  bgf:hasSource :ID-00000002 ;
  bgf:hasTarget :ID-00000001 .
